<script lang="ts">
  import { onMount } from 'svelte'
  import { api } from '$lib/api'
  let rows: any[] = []; let error = ''; let filter = 'open'; let pageNumber = 1; let pages = 1; let total = 0; let loading = false
  async function load() { loading = true; error = ''; try { const result = await api<{ data: any[]; pagination: { pages: number; total: number } }>(`/admin/reports?status=${filter}&page=${pageNumber}&limit=20`); rows = result.data; pages = Math.max(1, result.pagination.pages); total = result.pagination.total } catch (reason: any) { error = reason.message } finally { loading = false } }
  onMount(() => { void load() })
  async function update(report: any, status: string) { try { await api(`/admin/reports/${report._id}`, { method: 'PATCH', body: JSON.stringify({ status }) }); await load() } catch (reason: any) { error = reason.message } }
</script>
<main class="admin-content"><div class="page-title"><div><span class="kicker">TRUST & SAFETY</span><h1>Abuse reports</h1><p>Review reported public forms and track moderation decisions.</p></div><span class="count-pill">{total} total</span></div>{#if error}<div class="notice error">{error}</div>{/if}<div class="toolbar"><select bind:value={filter} onchange={() => { pageNumber = 1; void load() }}><option value="open">Open</option><option value="reviewing">Reviewing</option><option value="resolved">Resolved</option><option value="dismissed">Dismissed</option></select><button class="secondary-button" onclick={() => void load()}>Refresh</button></div><section class="report-list">{#each rows as report}<article class="panel report-card"><div class="report-head"><div><span class="status-pill">{report.status}</span><span class="role-pill">{report.reason}</span><h2>{report.form?.title || `/${report.slug}`}</h2><p>Reported {new Date(report.createdAt).toLocaleString()} {report.reporterEmail ? `· ${report.reporterEmail}` : ''}</p></div><select value={report.status} onchange={(event) => update(report, event.currentTarget.value)}><option value="open">Open</option><option value="reviewing">Reviewing</option><option value="resolved">Resolved</option><option value="dismissed">Dismissed</option></select></div>{#if report.details}<p class="report-details">{report.details}</p>{/if}</article>{/each}{#if !rows.length}<div class="panel table-empty">{loading ? 'Loading reports…' : 'No reports in this queue.'}</div>{/if}</section><div class="admin-pagination"><span>Page {pageNumber} of {pages}</span><div><button class="secondary-button" disabled={pageNumber <= 1 || loading} onclick={() => { pageNumber -= 1; void load() }}>Previous</button><button class="secondary-button" disabled={pageNumber >= pages || loading} onclick={() => { pageNumber += 1; void load() }}>Next</button></div></div></main>
